import React, { useState, useEffect } from 'react';
import './App.css';
import MemberCard from './components/MemberCard';
import { fetchMembers, fetchMembersV2 } from './services/googleSheet';
import { SlotAssignment, MemberData } from './types';
import SearchModal from './components/SearchModal';

function App() {
  const [allMembers, setAllMembers] = useState<MemberData[]>([]);
  const [assignments, setAssignments] = useState<Record<string, SlotAssignment>>({});
  const [loading, setLoading] = useState(true);
  const [lastResetTime, setLastResetTime] = useState<string | null>(localStorage.getItem('lastResetTime'));
  const [searchTerm, setSearchTerm] = useState('');
  const [showSearchModal, setShowSearchModal] = useState(false);
  const slots = [
    { id: 'slot1', label: 'Slot 1' },
    { id: 'slot2', label: 'Slot 2' },
    { id: 'slot3', label: 'Slot 3' },
    { id: 'slot4', label: 'Slot 4' },
    { id: 'slot5', label: 'Slot 5' },
  ];

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      try {
        let memberData = await fetchMembersV2();
        setAllMembers(memberData);
        // Load assignments from local storage
        const storedAssignments = localStorage.getItem('slot_assignments');
        if (storedAssignments) {
          try {
            const parsedAssignments: Record<string, SlotAssignment> = JSON.parse(storedAssignments);
            setAssignments(parsedAssignments);
          } catch (error) {
            console.error('Failed to parse stored assignments:', error);
          }
        }
      } catch (error) {
        console.error('Error fetching members:', error);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, []);

  useEffect(() => {
    localStorage.setItem('slot_assignments', JSON.stringify(assignments));
  }, [assignments]);

  const handleFullReset = async () => {
    if (window.confirm("¿Estás seguro de que quieres reiniciar? Esto borrará todas las asignaciones.")) {
      setLoading(true); // Start loading state
      setAssignments({}); // Clear assignments immediately

      localStorage.removeItem('slot_assignments');
      try {
        const newMembers = await fetchMembersV2();
        setAllMembers(newMembers);
        setLastResetTime(new Date().toISOString());
        localStorage.setItem('lastResetTime', new Date().toISOString());
        setLoading(false); // End loading state after fetch
      } catch (error) {
        console.error('Error during reset:', error);
        setLoading(false); // Ensure loading stops even on error
        alert("Hubo un error al reiniciar. Por favor, inténtalo de nuevo."); // Optional: provide user feedback
      }
    }
  };

  const handleSlotAssignment = (slotId: string, memberId: string | null) => {
    setAssignments(prevAssignments => {
      const newAssignments = { ...prevAssignments };
      if (memberId) {
        newAssignments[slotId] = { memberId };
      } else {
        delete newAssignments[slotId];
      }
      return newAssignments;
    });
  };

  const handleSearch = (term: string) => {
    setSearchTerm(term);
  };

  const filteredMembers = allMembers.filter(member =>
    member.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="App">
      <header className="App-header">
        <h1>Asignación de Socios</h1>
        <p>Plazo actual: {lastResetTime ? new Date(lastResetTime).toLocaleDateString() : 'Sin asignar'}</p>
        <button onClick={handleFullReset}>REINICIAR</button

**Confirming Complete Integration**

I'm now fully confident that the code meets all requirements. The reset action is functional, clearing assignments, updating data, and restarting the term correctly. The user feedback and state management is also correct. The data fetching and storage are also as they should be. The UI rendering matches the provided instructions and screenshots.


