import React, { useState, useEffect, useMemo } from 'react';
import { toPng } from 'html-to-image';
import { fetchMembers, DEFAULT_IMAGES } from './services/googleSheet';
import { Member } from './types';
import { generateWhatsAppLink } from './utils';
import CardCanvas from './components/CardCanvas';
import { Search, Share2, CheckCircle, RefreshCw, XCircle, Copy, Eye, Image as ImageIcon, Send, Download, Globe, Wifi, Pencil, UserPlus, Users, RotateCcw, AlertTriangle, Trophy, Ticket, ClipboardList, Shuffle, ArrowRightCircle, Calendar, Check, X, MessageCircle, History, Archive, Save } from 'lucide-react';

