            <div className="grid gap-3 sm:grid-cols-2 shrink-0">
               <a 
                href={getWhatsAppMessage(selectedPreviewData.member, generateLinkForMember(selectedPreviewData.member, lastResetTime, selectedPreviewData.slotId))}
