const SecureViewer: React.FC = () => {
  const [member, setMember] = useState<Member | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>('');
  const [referenceTimestamp, setReferenceTimestamp] = useState<number | undefined>(undefined);
  const [forcedImageUrl, setForcedImageUrl] = useState<string | undefined>(undefined);
  const [isExpired, setIsExpired] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
        const hash = window.location.hash;
        const queryString = hash.split('?')[1];
        const urlParams = new URLSearchParams(queryString);
        const id = urlParams.get('id');
        const timestampStr = urlParams.get('t'); 
        const slotIdStr = urlParams.get('slot');

        if (!id) { setError('Enlace inválido: falta el ID del socio.'); setLoading(false); return; }
        if (timestampStr) {
            const timestamp = parseInt(timestampStr);
            setReferenceTimestamp(timestamp);
            const expirationTime = timestamp + (96 * 60 * 60 * 1000);
            if (Date.now() > expirationTime) { setIsExpired(true); setLoading(false); return; }
        }
        if (slotIdStr) {
            const slotId = parseInt(slotIdStr);
            const slotConfig = PASS_SLOTS.find(s => s.slotId === slotId);
            if (slotConfig) setForcedImageUrl(slotConfig.imageUrl);
        }
        try {
            const allMembers = await fetchMembers();
            const found = allMembers.find(m => m.id === id);
            if (found) setMember(found); else setError('Socio no encontrado.');
        } catch (e) { setError('Error de conexión con la base de datos.'); } finally { setLoading(false); }
    };
    fetchData();
  }, []);

  if (loading) return <div className="min-h-screen flex items-center justify-center bg-neutral-900 text-white"><RefreshCw className="animate-spin mr-2" /> Cargando...</div>;
  if (isExpired) return <div className="min-h-screen flex flex-col items-center justify-center bg-neutral-900 p-8 text-center text-white"><div className="bg-red-500/20 p-6 rounded-full mb-6"><AlertTriangle className="w-16 h-16 text-red-500" /></div><h1 className="text-3xl font-bold mb-2">Enlace Caducado</h1><p className="text-gray-400 max-w-xs">Este pase de acceso ha expirado por seguridad. Contacta con la Peña.</p></div>;
  if (error || !member) return <div className="min-h-screen flex items-center justify-center bg-neutral-900 p-8 text-center text-red-400 font-bold">{error}</div>;

  return (
    <div className="min-h-screen bg-neutral-900 flex flex-col items-center justify-center secure-view">
      <div className="bg-green-500/10 px-5 py-2 mb-6 rounded-full border border-green-500/30"><p className="text-green-400 text-xs font-bold tracking-widest flex items-center gap-2 uppercase"><CheckCircle className="w-4 h-4"/> Pase Verificado</p></div>
      <CardCanvas memberId={member.id} memberName={member.name} imageUrl={forcedImageUrl || member.imageUrl} referenceTimestamp={referenceTimestamp} />
    </div>
  );
};

const App: React.FC = () => {
  const [route, setRoute] = useState<'dashboard' | 'view'>('dashboard');
  useEffect(() => {
    const handleRoute = () => { const hash = window.location.hash; setRoute(hash.includes('/view') ? 'view' : 'dashboard'); };
