      const pendingToWin = activeMembers.filter(m => !cycleHistory.includes(m.id));

      return {
          total: allMembers.length,
          active: activeMembers.length,
          pending: pendingToWin.length
      };
  }, [allMembers, cycleHistory]);


  const loadData = async () => {
    setLoading(true);
