      }
  };

  const updateWinnerStatus = (memberId: string, status: WinnerStatus) => {
      setWinnersStatus(prev => ({
          ...prev,
          // Si pulsan el mismo botón, se deselecciona (vuelve a pending)
          [memberId]: prev[memberId] === status ? 'pending' : status
      }));
