      let count = 0;

      lines.forEach(line => {
          // Busca filas que contengan "Ganador" (case insensitive)
          // Formato típico esperado: "ID NOMBRE ... Ganador ..."
          if (line.toLowerCase().includes('ganador')) {
              // Extrae el primer número de la línea (ID)
              const match = line.trim().match(/^(\d+)/);
              if (match) {
                  newHistory.push(match[1]);
                  count++;
              }
          }
      });

      if (count > 0) {
          setCycleHistory(newHistory);
          localStorage.setItem('raffle_cycle_history', JSON.stringify(newHistory));
          alert(`✅ Importación exitosa.\n\nSe han marcado ${count} socios como 'Ya Premiados'.\n\nEstos socios no entrarán en el sorteo hasta que se complete el ciclo.`);
          setShowCycleModal(false);
          setManualCycleInput('');
      } else {
          alert("⚠️ No se encontraron ganadores en el texto.\n\nAsegúrate de copiar las columnas del Excel incluyendo la columna donde pone 'Ganador'.");
      }
  };


  const handleAddReserve = (member: Member) => {
      if (!reserveList.find(m => m.id === member.id)) {
          setReserveList([...reserveList, member]);
          setShowReserveSearch(false);
          setSearchTerm('');
