  const closePreview = () => setSelectedPreviewData(null);
  const closeQuickShare = () => setQuickShareData(null);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
