import React, { useMemo, useState, useEffect } from 'react';
import { Loader2, Clock } from 'lucide-react';

interface CardCanvasProps {
  memberId: string;
  memberName: string;
  imageUrl?: string;
  referenceTimestamp?: number; // Optional: If provided, expiration is calculated from this time
}

const CardCanvas: React.FC<CardCanvasProps> = ({ memberId, memberName, imageUrl, referenceTimestamp }) => {
  const [imageState, setImageState] = useState<'loading' | 'success' | 'error'>('loading');
  const [currentCandidateIndex, setCurrentCandidateIndex] = useState(0);

  // Logo de la Peña para MARCA DE AGUA
  const PENA_LOGO_ID = "17pNVMd42F6pDU7LOCPjPZ-xrUckcYNMe";

  // ESTRATEGIA DE MARCA DE AGUA
  // Usamos el Thumbnail de Google como fuente, pero lo pasamos por el proxy para asegurar CORS y transparencia.
  const WM_SOURCE = `https://drive.google.com/thumbnail?id=${PENA_LOGO_ID}&sz=w800`;
  const WM_PROXY = `https://wsrv.nl/?url=${encodeURIComponent(WM_SOURCE)}&output=png`; // Forzamos PNG para transparencia

  const [watermarkSrc, setWatermarkSrc] = useState<string>(WM_PROXY);
  const [isWatermarkFallback, setIsWatermarkFallback] = useState(false);

  const handleWatermarkError = () => {
    if (!isWatermarkFallback) {
        // Fallback al directo si el proxy falla (se verá, pero quizás no deje descargar)
        setWatermarkSrc(WM_SOURCE);
        setIsWatermarkFallback(true);
    }
  };

  // ---------------------------------------------------------
  // EXPIRATION DATE LOGIC (Security Feature)
  // ---------------------------------------------------------
  const expirationString = useMemo(() => {
    const date = referenceTimestamp ? new Date(referenceTimestamp) : new Date();
    // 96 horas (4 días)
    date.setHours(date.getHours() + 96);

    const day = date.getDate().toString().padStart(2, '0');
    const month = (date.getMonth() + 1).toString().padStart(2, '0');

    return `${day}/${month}`;
  }, [referenceTimestamp]);

  // ---------------------------------------------------------
  // ESTRATEGIA DE IMAGEN DE FONDO (Optimización y Robustez)
  // ---------------------------------------------------------
  const imageCandidates = useMemo(() => {
    if (!imageUrl) return [];

    // Extraer ID de Google Drive
    const driveIdMatch = imageUrl.match(/\/d\/([^/]+)|id=([^&]+)/);
    const driveId = driveIdMatch ? (driveIdMatch[1] || driveIdMatch[2]) : null;

    // Si no es un enlace de Drive conocido, lo intentamos directo y proxificado
    if (!driveId) {
        return [
            `https://wsrv.nl/?url=${encodeURIComponent(imageUrl)}&w=1000&q=85&output=webp`, // Proxy Optimizado
            imageUrl // Directo
        ];
    }

    // Enlaces base de Google
    const googleThumbnailHighRes = `https://drive.google.com/thumbnail?id=${driveId}&sz=w2000`; // Buena calidad, rápido
    const googleDirect = `https://drive.google.com/uc?export=view&id=${driveId}`; // Lento, propenso a 403

    return [
        // 1. PROXY (WESERV) - PRIORIDAD MÁXIMA
        // - Garantiza cabeceras CORS (vital para html-to-image).
        // - Comprime a WebP y redimensiona a 1000px (fluidez en móviles).
        // - Cachea la imagen en sus servidores (velocidad).
        `https://wsrv.nl/?url=${encodeURIComponent(googleThumbnailHighRes)}&w=1000&q=85&output=webp`,

        // 2. GOOGLE THUMBNAIL API (FALLBACK RÁPIDO)
        // - Si el proxy falla, usamos la API de miniaturas de Google.
        // - Es rápida, pero a veces falla en CORS para canvas.
        googleThumbnailHighRes,

        // 3. GOOGLE DIRECT LINK (ÚLTIMO RECURSO)
        googleDirect
    ];
  }, [imageUrl]);

  const currentSrc = imageCandidates[currentCandidateIndex];

  // Reset cuando cambia la URL
  useEffect(() => {
    if (imageUrl) {
        setImageState('loading');
        setCurrentCandidateIndex(0);
    } else {
        setImageState('error');
    }
  }, [imageUrl]);

  const handleImageError = () => {
    if (currentCandidateIndex < imageCandidates.length - 1) {
        // Pasar al siguiente candidato
        setCurrentCandidateIndex(prev => prev + 1);
    } else {
        setImageState('error');
    }
  };

  const handleImageLoad = () => {
      setImageState('success');
  };

  // ---------------------------------------------------------
  // SVG FALLBACK (Si todo falla)
  // ---------------------------------------------------------
  const svgFallbackUrl = useMemo(() => {
    const width = 600;
    const height = 900; 
    const svgString = `
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}">
