          id: Date.now().toString(),
          date: Date.now(),
          matchName: matchName,
          winners: [...raffleWinners], 
          reserves: [...reserveList]
      };

      const safeHistory = Array.isArray(matchHistory) ? matchHistory : [];
      const updatedHistory = [newRecord, ...safeHistory];

      setMatchHistory(updatedHistory);
      localStorage.setItem('raffle_match_history', JSON.stringify(updatedHistory));

      setMatchName('');
      setRaffleWinners([]);
      setReserveList([]);
      setReserveWinners([]);
      setWinnersStatus({});
      alert("✅ Jornada cerrada.");
      setCurrentTab('history');
