                  const link = document.createElement('a');
                  link.download = `Sorteo_${matchName || 'Abonos'}.png`;
                  link.href = URL.createObjectURL(blob);
                  link.click();
                  alert("⚠️ No se pudo copiar al portapapeles. Se ha descargado la imagen.");
