        setImageState('error');
    }
  }, [imageUrl]);

  const handleImageError = () => {
    if (currentCandidateIndex < imageCandidates.length - 1) {
        // Pasar al siguiente candidato
        setCurrentCandidateIndex(prev => prev + 1);
    } else {
        setImageState('error');
    }
  };

  const handleImageLoad = () => {
      setImageState('success');
